import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"管理工程角色","description":"创建工程角色、核对角色代码，分配用户并配置可调用数据点，避免与组织角色混淆。","frontmatter":{"title":"管理工程角色","description":"创建工程角色、核对角色代码，分配用户并配置可调用数据点，避免与组织角色混淆。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/project-roles.md","filePath":"zh/使用指南/管理工程角色.md"}'),i={name:"zh/guide/project-roles.md"};function l(s,a,n,d,h,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="管理工程角色" tabindex="-1">管理工程角色 <a class="header-anchor" href="#管理工程角色" aria-label="Permalink to &quot;管理工程角色&quot;">​</a></h1><p>工程角色控制工程用户在页面中的数据调用范围。它不同于组织账号的“管理员、工程人员、运维人员”。</p><p>角色维护在工程的 **“用户预设”**中完成，需要工程创建者或组织管理员权限。先核对工程，再选择 <strong>“角色管理”</strong>。</p><h2 id="_1-创建角色" tabindex="-1">1. 创建角色 <a class="header-anchor" href="#_1-创建角色" aria-label="Permalink to &quot;1. 创建角色&quot;">​</a></h2><ol><li>点击 <strong>“创建角色”</strong>。</li><li>填写“角色编码”“角色名称”，按需要补充“角色描述”。</li><li>核对页面显示的 <strong>“将保存的角色编码”</strong>，再保存。</li><li>确认“角色创建成功”，重新读取列表核对名称、代码与状态。</li></ol><p>新建代码会按页面规则整理大小写、空白和前缀，不能只凭输入框原文推定最终代码。后续导入用户或交流角色时，复制实际保存的代码。</p><p>新建角色没有自动获得全部数据点。先创建角色，再到<a href="/induframe-docs/zh/guide/workspace-datapoints.html">应用开发的数据点管理</a>配置“调用权限”。</p><h2 id="_2-分配给用户" tabindex="-1">2. 分配给用户 <a class="header-anchor" href="#_2-分配给用户" aria-label="Permalink to &quot;2. 分配给用户&quot;">​</a></h2><p>回到 <strong>“用户管理”</strong>，为已有用户使用 <strong>“分配角色”</strong>，或创建用户时选择这个角色。</p><p>保存后，核对用户行显示的角色。角色存在但没有绑定用户时，不会自动授予任何人访问资格。一个用户绑定多个角色时，也应逐项核对，避免额外授权。</p><h2 id="_3-配置可调用的数据点" tabindex="-1">3. 配置可调用的数据点 <a class="header-anchor" href="#_3-配置可调用的数据点" aria-label="Permalink to &quot;3. 配置可调用的数据点&quot;">​</a></h2><p>在“应用开发”选择“数据点”，勾选目标点后使用 <strong>“调用权限”</strong>。这里按本次选择的点为角色授予或撤销调用，不是编辑角色名称的入口。</p><p>内置角色及已经具有“全部数据点”的角色不在这个点位选择对话框中编辑。出现不可修改的提示时，先理解角色范围，不通过反复取消勾选绕过。</p><h2 id="_4-修改、停用和删除" tabindex="-1">4. 修改、停用和删除 <a class="header-anchor" href="#_4-修改、停用和删除" aria-label="Permalink to &quot;4. 修改、停用和删除&quot;">​</a></h2><p>编辑角色时，核对完整角色代码和名称。修改已有代码不会沿用新建时的自动整理规则，应同时更新使用旧代码的导入资料或其他引用。</p><p>调整状态或权限前先通知相关使用者，检查绑定用户数。<strong>删除角色不可恢复</strong>，已绑定用户会失去该角色及权限；系统角色不允许删除。</p><p>本页修改的是工程身份预设。需要让正式部署使用新配置时，按工程发布和更新安排同步，再验证用户真正能访问的页面与数据，不仅查看列表。</p><h2 id="怎样确认完成" tabindex="-1">怎样确认完成 <a class="header-anchor" href="#怎样确认完成" aria-label="Permalink to &quot;怎样确认完成&quot;">​</a></h2><ul><li>角色名称、实际代码、状态和绑定用户符合预期。</li><li>数据点调用权限保存后重新读取仍正确。</li><li>预览使用对应工程用户时，画面和可调用范围符合预期。</li><li>正式部署更新后，另行验证运行身份，不拿开发预览代替。</li></ul><p>下一步：<a href="/induframe-docs/zh/guide/project-users.html">管理工程用户</a> · <a href="/induframe-docs/zh/guide/workspace-datapoints.html">应用开发数据点管理</a>。</p>',20)])])}const u=e(i,[["render",l]]);export{c as __pageData,u as default};
